"use strict";
import { useQuery } from "@tanstack/react-query";
import { useAccount } from "hooks/useAccount";
import { Contract } from "@ethersproject/contracts";
import { useEthersProvider } from "hooks/useEthersProvider";
const BRIBE_ABI = [
  "function rewardsListLength() external view returns (uint256)",
  "function rewards(uint256 index) external view returns (address)",
  // These might be available for total incentive info
  "function rewardData(address token) external view returns (uint256 periodFinish, uint256 rewardRate, uint256 lastUpdateTime, uint256 rewardPerTokenStored)",
  "function left(address token) external view returns (uint256)",
  // Fallback functions
  "function balanceOf(address) external view returns (uint256)"
];
const ERC20_ABI = [
  "function symbol() external view returns (string)",
  "function decimals() external view returns (uint8)",
  "function balanceOf(address) external view returns (uint256)"
];
export function useChainIncentiveData(gauges = []) {
  const { chainId } = useAccount();
  const provider = useEthersProvider();
  return useQuery({
    queryKey: ["chain-incentive-data", chainId, gauges.map((g) => g.id).sort()],
    queryFn: async () => {
      if (!provider) {
        throw new Error("No ethereum provider available for fetching incentive data");
      }
      if (!chainId) {
        throw new Error("No chainId available for fetching incentive data");
      }
      if (gauges.length === 0) {
        return [];
      }
      const incentiveData = [];
      for (const gauge of gauges) {
        if (!gauge.bribeContract || gauge.bribeContract === "0x0000000000000000000000000000000000000000") {
          continue;
        }
        try {
          const bribeContract = new Contract(gauge.bribeContract, BRIBE_ABI, provider);
          const rewardTokens = [];
          let rewardsLength = 0;
          try {
            rewardsLength = await bribeContract.rewardsListLength();
          } catch (error) {
            console.warn(`Failed to get rewards length for gauge ${gauge.id} bribe contract ${gauge.bribeContract}:`, error);
            continue;
          }
          for (let i = 0; i < rewardsLength; i++) {
            try {
              const tokenAddress = await bribeContract.rewards(i);
              if (tokenAddress === "0x0000000000000000000000000000000000000000") {
                continue;
              }
              let totalAmount = "0";
              try {
                const leftAmount = await bribeContract.left(tokenAddress);
                totalAmount = leftAmount.toString();
              } catch (error) {
                try {
                  const tokenContract = new Contract(tokenAddress, ERC20_ABI, provider);
                  const balance = await tokenContract.balanceOf(gauge.bribeContract);
                  totalAmount = balance.toString();
                } catch (balanceError) {
                }
              }
              let symbol = "TOKEN";
              let decimals = 18;
              try {
                const tokenContract = new Contract(tokenAddress, ERC20_ABI, provider);
                symbol = await tokenContract.symbol();
                decimals = await tokenContract.decimals();
              } catch (tokenError) {
              }
              const isActive = totalAmount !== "0" && parseInt(totalAmount) > 0;
              rewardTokens.push({
                address: tokenAddress,
                symbol,
                decimals,
                totalAmount,
                isActive
              });
            } catch (error) {
            }
          }
          if (rewardTokens.length > 0) {
            incentiveData.push({
              gaugeId: gauge.id,
              bribeContract: gauge.bribeContract,
              rewardTokens
            });
          }
        } catch (error) {
          console.error(`Failed to process gauge ${gauge.id} incentive data:`, error);
        }
      }
      console.log(`\u2705 Successfully fetched incentive data for ${incentiveData.length} gauges`);
      return incentiveData;
    },
    enabled: Boolean(provider && chainId && gauges.length > 0),
    staleTime: 15e3,
    // 15 seconds - much faster than subgraph
    refetchInterval: 3e4,
    // Refetch every 30 seconds for real-time updates
    retry: 2
  });
}
export function calculatePoolIncentivesFromChain(chainIncentives, gaugeId, emissions) {
  let totalIncentives = 0;
  let totalEmissions = 0;
  const incentiveDetails = [];
  if (emissions && emissions !== "0") {
    try {
      totalEmissions = parseFloat((BigInt(emissions) / BigInt(10 ** 18)).toString());
    } catch (error) {
      console.warn("Failed to parse emissions:", emissions, error);
    }
  }
  const gaugeIncentives = chainIncentives.find((incentive) => incentive.gaugeId === gaugeId);
  if (gaugeIncentives) {
    gaugeIncentives.rewardTokens.forEach((token) => {
      if (token.isActive && token.totalAmount !== "0") {
        try {
          const decimals = token.decimals || 18;
          const amount = parseFloat((BigInt(token.totalAmount) / BigInt(10 ** decimals)).toString());
          if (amount > 0) {
            totalIncentives += amount;
            incentiveDetails.push({
              token: token.address,
              amount: amount.toLocaleString(void 0, { maximumFractionDigits: 2 }),
              symbol: token.symbol
            });
          }
        } catch (error) {
          console.warn("Failed to parse incentive amount:", token.totalAmount, error);
        }
      }
    });
  }
  const totalRewards = totalIncentives + totalEmissions;
  let incentivesFormatted = "-";
  if (incentiveDetails.length > 0) {
    incentivesFormatted = incentiveDetails.map((detail) => `${detail.amount} ${detail.symbol || "tokens"}`).join(" + ");
  }
  return {
    totalIncentives,
    totalEmissions,
    totalRewards,
    incentivesFormatted,
    incentiveDetails
  };
}
